+/** Resolve encryption policy for a new room, with server policy taking precedence over .well-known. */
+export async function checkUserIsAllowedToChangeEncryption(
+    client: MatrixClient,
+    chatPreset: Preset,
+): Promise<AllowedEncryptionSetting> {
+    const serverForcesEncryption = await client.doesServerForceEncryptionForPreset(chatPreset);
+    const wellKnownDisablesEncryption = shouldForceDisableEncryption(client);
+
+    if (serverForcesEncryption) {
+        if (wellKnownDisablesEncryption) {
+            console.warn("Conflicting encryption policies: server requires encryption but .well-known disables it");
+        }
+        return { allowChange: false, forcedValue: true };
+    }
+    if (wellKnownDisablesEncryption) return { allowChange: false, forcedValue: false };
+    return { allowChange: true };
+}
